# For each demo: list the DUPLICATE SHAPE GROUP (two diff-color same-shape objects), mark which changed, 
# and distances between them and the PRE-EXISTING target-color object(s). Then test discriminators.
pairs=list(range(1,9))
for p in pairs:
    I=G[f'Demo pair {p} input']; O_=G[f'Demo pair {p} output']
    chgset={(r,c) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]!=O_[r][c]}
    bg=comps4(I)
    byshape=collections.defaultdict(list)
    for o in bg: byshape[nrm(o[1])].append(o)
    dupekeys=[k for k in byshape if len(k)>=2 and len(set(o[0] for o in byshape[k]))>1]
    for k in dupekeys:
        objs=byshape[k]
        chg=[o for o in objs if set(o[1])&chgset]
        if chg:
            tgtc=int(O_[list(chgset)[0]][0])
            # locate pre-existing target objects (same color, disjoint from change)
            tgts=[tt for tt in comps4(I) if tt[0]==tgtc and set(tt[1]).isdisjoint(chgset)]
            def top(o): return (min(r for r,x in o[1]), min(c for _,c in o[1]))
            A=top(objs[0]); B=top(objs[1])
            dAB=man(A,B)
            dtA=min(man(A,top(t)) for t in tgts) if tgts else None
            dtB=min(man(B,top(t)) for t in tgts) if tgts else None
            print(f'---pair{p}: CHANGED obj color={objs[0][0]} at A,A2=B')
            print('   dup centers:',A,'vs',B,'dist=',dAB,'dists_to_tgt_objs:',dtA,det(dtB)if False else (min(man(B,top(t)) for t in tgts) if tgts else None),'which_changed_A',objs[0] in chg)

