# Rule: find same-shape pair with two different colors -> INT copy gets recolored to color of largest singleton object (singleton = color class with exactly one object; tie-breaker: larger size)
def solve(I):
    bg=comps(I); H,W=len(I),len(I[0])
    # group components by normalized shape across all colors
    bysn=collections.defaultdict(list)
    for o in bg: bysn[norm(o[1])].append(o)
    best=None
    for sn,gr in bysn.items():
        if len(gr)<2: continue
        colors={o[0] for o in gr}
        if len(colors)>=2:
            ints=[o for o in gr if not onborder(o[1],H,W)]
            bords=[o for o in gr if onborder(o[1],H,W)]
            if ints and bords:
                # pick the INT as target; but which INT if multiple? In demos only one per group.
                tgt=ints[0]
                def mk():
                    sing=[c for c,_ in bg if _==c]
                    sng_size={}
                    for c in set(o[0] for o in bg):
                        s=sum(len(o[1]) for o in bg if o[0]==c)
                        sng_size[c]=s
                    ch=max(sng_size,key=sng_size.get)
                    return ch
                best=tgt
                break
    out=[list(row) for row in I]
    if best is None:
        # fallback: no dup-pair found -> select interior candidate whose color is not singleton-ish? handle later
        pass
    else:
        newc=max(collections.Counter(c for c,cell in bg).items(), key=lambda kv:(kv[1]-1)*(-1))[0]
        # actually use the marker color rule: largest singleton color
        cnt=collections.Counter(c for c,cell in bg)
        sng=[c for c,n in cnt.items() if n==1]
        sizes={c:max(sum(l) for l in [x for x in bg if x[0]==c][0][1]) for c in sng}
        newc=max(sng,key=lambda c:sizes.get(c,0))
        for cell in best[1]:
            out[cell[0]][cell[1]]=newc
    return out

